<?php
require_once 'includes/auth.php';require_once 'includes/dashboard.php';require_admin();
$catalog=cds_dashboard_widgets_catalog();$settings=cds_dashboard_settings();
if($_SERVER['REQUEST_METHOD']==='POST'){$enabled=array_values(array_filter(array_map('strval',$_POST['enabled']??[])));$order=array_values(array_filter(array_map('strval',explode(',',$_POST['order']??''))));cds_dashboard_save($enabled,$order);cds_audit_log('update','dashboard',['target'=>'widget_settings','enabled'=>$enabled]);flash('Đã lưu bố cục trang chủ.');header('Location: dashboard_settings.php');exit;}
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cấu hình trang chủ</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:#f4f7fb}.wrap{max-width:1000px;margin:auto}.widget-row{display:grid;grid-template-columns:34px 48px 1fr auto;align-items:center;gap:12px;padding:14px 16px;margin-bottom:10px;border:1px solid #e2e8f0;border-radius:14px;background:#fff;cursor:grab}.widget-row.dragging{opacity:.45}.handle{color:#94a3b8}.icon{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#eff6ff;color:#2563eb;font-size:19px}.card{border:1px solid #e2e8f0;border-radius:18px;box-shadow:0 5px 20px rgba(15,23,42,.05)}</style></head><body><?php $nav_title='Cấu hình trang chủ';$nav_icon='bi-sliders';$nav_color='#2563eb';$nav_module='admin';include __DIR__.'/includes/nav_top.php';?><main class="container py-4 wrap"><?php show_flash(); ?><div class="d-flex justify-content-between align-items-start mb-3"><div><h3 class="mb-1">Bố cục trang chủ</h3><p class="text-muted">Bật, tắt và kéo thả để sắp xếp các khối thông tin cho toàn hệ thống.</p></div><a href="admin.php" class="btn btn-outline-secondary"><i class="bi bi-arrow-left"></i> Trang chủ</a></div><form method="post" class="card p-3 p-md-4"><input type="hidden" name="order" id="widgetOrder"><div id="widgetList"><?php foreach($settings['order'] as $id):if(!isset($catalog[$id]))continue;$w=$catalog[$id];?><div class="widget-row" draggable="true" data-id="<?= e($id) ?>"><i class="bi bi-grip-vertical handle"></i><span class="icon"><i class="bi <?= e($w['icon']) ?>"></i></span><div><strong><?= e($w['title']) ?></strong><small class="d-block text-muted"><?= $w['module']?'Theo quyền module '.$w['module']:'Dùng chung' ?></small></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="enabled[]" value="<?= e($id) ?>" <?= in_array($id,$settings['enabled'],true)?'checked':'' ?>></div></div><?php endforeach;?></div><div class="d-flex justify-content-end mt-3"><button class="btn btn-primary px-4"><i class="bi bi-floppy"></i> Lưu bố cục</button></div></form></main><script>const list=document.getElementById('widgetList'),order=document.getElementById('widgetOrder');function sync(){order.value=[...list.children].map(x=>x.dataset.id).join(',')}sync();let dragged=null;list.addEventListener('dragstart',e=>{dragged=e.target.closest('.widget-row');dragged?.classList.add('dragging')});list.addEventListener('dragend',()=>{dragged?.classList.remove('dragging');dragged=null;sync()});list.addEventListener('dragover',e=>{e.preventDefault();if(!dragged)return;const items=[...list.querySelectorAll('.widget-row:not(.dragging)')],next=items.find(x=>e.clientY<x.getBoundingClientRect().top+x.offsetHeight/2);list.insertBefore(dragged,next||null)})</script></body></html>

